import { map } from './modules/maploader';
import { generateAllMarkerIcons } from './modules/icons-loader';
import { handleInputs } from './modules/filters-handlers';
import { handleTabs } from './modules/tabs-handler';
import { useDataStore } from './store/data-store';
import { createMarkerLayer, waitForSourceAndUpdate } from './modules/markers';
import { loadBoundaries } from './modules/boundaries';
import { hideLoader } from './modules/loader';
import makeImageBar from './modules/image-bar';
import processStyles from './modules/process-styles';
import { useFiltersStore } from './store/filters-store';
import { useTabsStore } from './store/tabs-store';
import { handleAccess } from './modules/handle-access';
import { buildSitesNearby } from './modules/build-sites-nearby';

const timer = Date.now();
const { getSites, setInitialized } = useDataStore.getState();
const { getTabsState } = useTabsStore.getState();
const { getAllFilters } = useFiltersStore.getState();

// const tabsState = createTabState();

function waitForMapLoad() {
  return new Promise((resolve) => {
    if (map.loaded()) {
      resolve();
    } else {
      map.once('load', () => resolve());
    }
  });
}

async function buildMapFilters() {
  if (!window.location.pathname.includes('/map')) buildSitesNearby();
  processStyles();
  generateAllMarkerIcons();
  loadBoundaries();
  await Promise.all([waitForMapLoad()])
    .then(async () => {
      const filtersState = getAllFilters();
      const tabsState = getTabsState();

      // console.log('Filters: ');
      // console.log(filtersState);
      // console.log('Tabs: ');
      // console.log(tabsState);
      handleInputs(filtersState);
      handleTabs(tabsState);

      const sites = getSites();
      // console.log('Sites: ', sites.length);
      await createMarkerLayer(sites);
      makeImageBar();
      handleAccess();
      waitForSourceAndUpdate('site-points', () => {
        // console.log('Sorce initialized, map event fired initialized');
        map.fire('initialized');
        setInitialized(true);
        hideLoader();
      });
      // console.log(`Rendered all in ${Date.now() - timer} ms`);
    })
    .catch(console.error);
}

if (!window.dataInitialized) {
  window.buildMapFilters = buildMapFilters;
} else {
  buildMapFilters();
}
