import variables from '../blocks-layout/variables.css';
import hoverPopup from '../blocks-layout/hover-popup.css';
import sitePopup from '../blocks-layout/site-popup.css';
import image from '../blocks-layout/image.css';
import scrollOverlay from '../blocks-layout/map-scroll-overlay.css';
import controlls from '../blocks-layout/controlls.css';

function processSyles() {
  const styles = [variables, scrollOverlay, controlls, hoverPopup, sitePopup, image];
  const styleElement = document.createElement('style');
  styleElement.innerHTML = `${styles.join('')}`;
  document.body.append(styleElement);
}

export default processSyles;
