import { initialFiltersState, useFiltersStore } from '../store/filters-store';
import { useDataStore } from '../store/data-store';
import { useTabsStore } from '../store/tabs-store';
import { filtersInputs } from './filters-handlers';
import { getSiteType, updateBoundaryOutline } from './markers';
import { map } from './maploader';
import sleep from '../utils/sleep';
import { setUrlQuery } from './handle-url-queries';

const { setSelectedInputLevel, getAllFilters, getSelectedInputLevel, getInputHandlers } =
  useFiltersStore.getState();

const filtersInputsMap = {
  watershed: 'watershed',
  waterbody: 'waterbody',
  state: 'state',
  county: 'county',
  town: 'town',
  organization: 'organization',
  category: 'category',
  site: 'site',
  clean: 'clean',
  boating: 'boating',
  'not-clean': 'notClean',
  month: 'month',
  year: 'year',
  old: 'old',
};

const waterTabFilters = ['watershed', 'waterbody'];
const regionTabFilters = ['state', 'county', 'town'];

const {
  getWaterSheds,
  getWaterBodies,
  getOrganizations,
  getCategories,
  getSites,
  getStates,
  getCounties,
  getTowns,
  getInitialized,
  getDrawnBoundaryType,
} = useDataStore.getState();

const { getIsAdministrative } = useTabsStore.getState();

const dataInputsMap = {
  states: 'states-select',
  counties: 'counties-select',
  towns: 'towns-select',
  watersheds: 'watersheds-select',
  waterbodies: 'waterbodies-select',
  organizations: 'monitoring-select',
  categories: 'categories-select',
  sites: 'sites-select',
};

function createOption(text, value, classes) {
  const option = document.createElement('option');
  option.value = value;
  option.textContent = text;
  option.classList.add(...classes);
  return option;
}

function createDataState() {
  return {
    states: getStates(),
    counties: getCounties(),
    towns: getTowns(),
    watersheds: getWaterSheds(),
    waterbodies: getWaterBodies(),
    organizations: getOrganizations(),
    categories: getCategories(),
    sites: getSites(),
  };
}

function resetInput(input) {
  if (input.element.type !== 'checkbox') {
    // console.log(`Skipping reset checkbox ${input.element.id}`);
    // console.log(`resetting input: ${input.element.id}`);
    const dataState = createDataState();
    input.element.innerHTML = '';
    input.element.append(input.emptyOption);

    const dataId = Object.entries(dataInputsMap).find(
      ([key, value]) => value === input.element.id
    )[0];
    try {
      dataState[dataId].forEach((element) => {
        const option = document.createElement('option');
        option.classList.add('map_filter-option', `map_filter-option--${dataId}`);
        option.value = element.id;
        option.textContent = element.name;
        input.element.append(option);
      });
      input.setFunction('');
      if (input.element.type !== 'checkbox') {
        input.element.classList.remove('input--active');
        disableResetBtn(input);
      }
      setUrlQuery(input.inputParam, '');
    } catch (error) {
      throw error;
    }
  }
}

function resetAreaInputs() {
  const sortedInputs = getSortedInputsByDependency(filtersInputs);
  for (let input of sortedInputs) {
    if (input.dependencyLevel > 2) {
      break;
    }
    resetInput(input);
  }
}

function handleZeroResults(select) {
  const keyWords = {
    site: 'sites',
    category: 'categories',
  };

  if (select.inputParam === 'site' || select.inputParam === 'category') {
    select.element.innerHTML = '';

    const option = createOption(`No ${keyWords[select.inputParam]}..`, 'none', [
      'map_filter-option',
      'map_filter-option--sites',
    ]);

    select.element.append(option);
    select.setFunction('');
    if (select.element.type !== 'checkbox') {
      select.element.classList.remove('input--active');
      disableResetBtn(select);
    }
    setUrlQuery(select.inputParam, '');
  } else {
    console.error(`Unexpected 0 results in ${select.element.id}`);
  }
}

function handleOneResult(select, option, needsPrefill) {
  const selectedInputLevel = getSelectedInputLevel();
  if (select.dependencyLevel < selectedInputLevel) {
    select.element.value = option.value;
  } else {
    select.element.innerHTML = '';
    select.element.append(select.emptyOption);
    select.element.append(option);
    if (needsPrefill) {
      option.selected = true;
      setSelectedInputLevel(select.dependencyLevel);
    } else {
      select.emptyOption.selected = true;
    }
    // console.log(`Set level: ${select.dependencyLevel}`);
  }

  select.setFunction(option.value);
  if (select.element.type !== 'checkbox' && needsPrefill) {
    select.element.classList.add('input--active');
    enableResetBtn(select);
  }
  setUrlQuery(select.inputParam, option.value);
}

function reRenderInputs(state) {
  if (state) {
    const handlers = getInputHandlers();
    const inputsToDispatch = [];
    filtersInputs.forEach((input, index) => {
      const filterKey = filtersInputsMap[input.inputParam];
      if (state[filterKey] !== initialFiltersState[filterKey]) {
        inputsToDispatch.push({ input, handler: handlers[index] });
      }
    });

    const sortedDispatches = [...inputsToDispatch];
    sortedDispatches.sort((a, b) => a.input.dependencyLevel - b.input.dependencyLevel);

    async function dipatchHandlersFromState() {
      for (const dispatch of sortedDispatches) {
        const { input, handler } = dispatch;
        const event = {
          target: input.element,
        };
        const filterKey = filtersInputsMap[input.inputParam];

        if (input.element.type === 'checkbox') {
          input.element.checked = state[filterKey];
        } else {
          const options = input.element.querySelectorAll('.map_filter-option');
          options.forEach((option) => {
            if (option.value === state[filterKey]) {
              option.selected = true;
            }
          });
        }

        handler(event);
        // console.log('handler');
        await sleep(100);
      }
    }
    const initialized = getInitialized();
    if (initialized) dipatchHandlersFromState();
    else {
      map.once('initialized', dipatchHandlersFromState);
    }
  } else {
    filtersInputs.forEach((input) => {
      resetInput(input);
    });
  }
}

function resetCheckboxes() {
  filtersInputs.forEach((filter) => {
    if (filter.element.type === 'checkbox') {
      filter.setFunction(false);
      filter.element.checked = false;
      setUrlQuery(filter.inputParam, '');
    }
  });
}

function filterInput(select, needsPrefill = true) {
  const selectedInputLevel = getSelectedInputLevel();
  const filteredOptions = select.optionsFilterFunction();
  try {
    switch (filteredOptions.length) {
      case 0: {
        handleZeroResults(select);
        break;
      }
      case 1: {
        if (select.required) {
          handleOneResult(select, filteredOptions[0], needsPrefill);
        } else {
          fillSelectWithOptions(select, filteredOptions);
        }
        break;
      }
      default: {
        if (selectedInputLevel < select.dependencyLevel) {
          fillSelectWithOptions(select, filteredOptions);
        }
        break;
      }
    }
  } catch (error) {
    throw error;
  }
}

function fillSelectWithOptions(select, options) {
  select.element.innerHTML = ``;
  select.element.append(select.emptyOption);
  options.forEach((option) => {
    select.element.append(option);
  });
  select.setFunction('');

  if (select.element.type !== 'checkbox') {
    select.element.classList.remove('input--active');
    disableResetBtn(select);
  }
  setUrlQuery(select.inputParam, '');

  // console.log(`Filling select ${select.element.id}... with data:`);
  // console.log(options);
}

function processInputsResets(selectedInput) {
  const selectedInputLevel = getSelectedInputLevel();

  const inputs = getSortedInputsByDependency(getNextInputs(selectedInputLevel));
  for (const input of inputs) {
    resetInput(input);
  }

  processInputsFiltering(selectedInput);
}

function processInputsFiltering(selectedInput) {
  const selectedInputLevel = getSelectedInputLevel();

  // console.log(`process sorting.. level:${selectedInputLevel}`);
  const inputs = getSortedInputsByDependency();
  const isManyToMany =
    selectedInput.inputParam === 'organization' || selectedInput.inputParam === 'category';

  if (
    selectedInput.element.type !== 'checkbox' &&
    // selectedInput.inputParam !== 'organization' &&
    selectedInput.element.value &&
    selectedInput.element.value !== 'none'
  )
    for (const input of inputs) {
      if (input.dependencyLevel < selectedInputLevel && input.element.type !== 'checkbox') {
        if (isManyToMany) {
          const filteredOptions = input.optionsFilterFunction();
          filterMTMInput(input, filteredOptions);
        } else {
          resetInput(input);
        }
      }
    }

  for (const input of inputs) {
    if (
      input.element.type === 'checkbox' ||
      input.dependencyLevel === selectedInputLevel ||
      (isManyToMany && input.dependencyLevel < selectedInputLevel)
    ) {
      continue;
    }

    filterInput(input);
  }
}

function filterMTMInput(select, filteredOptions) {
  const allOptions = buildAllOptions(select);

  const prevValue =
    select.element.value && select.element.value !== 'none' ? select.element.value : '';

  const isPrevStillValid = prevValue ? filteredOptions.some((o) => o.value === prevValue) : false;

  select.element.innerHTML = '';
  select.element.append(select.emptyOption);
  allOptions.forEach((o) => select.element.append(o));

  if (isPrevStillValid) {
    select.element.value = prevValue;
    select.setFunction(prevValue);
    select.element.classList.add('input--active');
    enableResetBtn(select);
    setUrlQuery(select.inputParam, prevValue);
  } else {
    select.setFunction('');
    select.element.classList.remove('input--active');
    disableResetBtn(select);
    setUrlQuery(select.inputParam, '');
  }
}

function buildAllOptions(select) {
  const dataState = createDataState();
  const entry = Object.entries(dataInputsMap).find(([_, id]) => id === select.element.id);
  const dataId = entry ? entry[0] : null;
  const items = dataId ? dataState[dataId] : [];

  return items.map((el) => {
    const opt = document.createElement('option');
    opt.classList.add('map_filter-option', `map_filter-option--${dataId}`);
    opt.value = el.id;
    opt.textContent = el.name;
    return opt;
  });
}

//Filter sites with applied filters
function filterSites() {
  const dataState = createDataState();
  const filterState = getAllFilters();

  // console.log('Filter state:');
  // console.log(filterState);
  const isAdministrative = getIsAdministrative();

  const filterResult = dataState.sites
    .filter((site) => {
      if (isAdministrative) {
        if (filterState.state && filterState.state !== 'none' && site.state !== filterState.state) {
          return false;
        }
        if (
          filterState.county &&
          filterState.county !== 'none' &&
          site.county !== filterState.county
        ) {
          return false;
        }
        if (filterState.town && filterState.town !== 'none' && site.town !== filterState.town) {
          return false;
        }
      } else {
        if (
          filterState.watershed &&
          filterState.watershed !== 'none' &&
          site.watershed !== filterState.watershed
        ) {
          return false;
        }
        if (
          filterState.waterbody &&
          filterState.waterbody !== 'none' &&
          site.waterbody !== filterState.waterbody
        ) {
          return false;
        }
      }
      if (
        filterState.organization &&
        filterState.organization !== 'none' &&
        !site.organizations.some((item) => item === filterState.organization)
      ) {
        return false;
      }
      if (
        filterState.category &&
        filterState.category !== 'none' &&
        !site.categories.some((item) => item === filterState.category)
      ) {
        return false;
      }
      if (filterState.site && filterState.site !== 'none' && site.id !== filterState.site) {
        return false;
      }
      return true;
    })
    .filter((site) => {
      const siteType = getSiteType(site);
      const hasClear = filterState.clean && siteType.quality === 'clean';
      const hasBoating = filterState.boating && siteType.quality === 'boat';
      const hasNotClean = filterState.notClean && siteType.quality === 'notClean';

      const result =
        (!filterState.clean && !filterState.boating && !filterState.notClean) ||
        hasClear ||
        hasBoating ||
        hasNotClean;
      return result;
    })
    .filter((site) => {
      const siteType = getSiteType(site);
      const hasMonth = filterState.month && siteType.relevance === 'month';
      const hasYear = filterState.year && siteType.relevance === 'year';
      const hasOld = filterState.old && siteType.relevance === 'old';
      return (
        (!filterState.month && !filterState.year && !filterState.old) ||
        hasMonth ||
        hasYear ||
        hasOld
      );
    });

  // console.log('Curent sites:');
  // console.log(filterResult);
  return filterResult;
}

//Reset filter
function handleResetFilterButton(input) {
  const isAdministrative = getIsAdministrative();
  const filters = filtersInputs.filter(
    (inp) =>
      inp.element.type !== 'checkbox' &&
      ((isAdministrative && !waterTabFilters.includes(inp.inputParam)) ||
        (!isAdministrative && !regionTabFilters.includes(inp.inputParam)))
  );
  const nextInputs = getSortedInputsByDependency(getNextInputs(input.dependencyLevel));
  const drawnBoundaryType = getDrawnBoundaryType();
  if (drawnBoundaryType) {
    const drawnInput = filtersInputs.find((filter) => filter.inputParam === drawnBoundaryType);
    const boundaryNeedsToClear = input.dependencyLevel <= drawnInput.dependencyLevel;
    if (boundaryNeedsToClear) updateBoundaryOutline({ clearOnly: true });
  }

  resetInput(input);
  const prevInput = filters[filters.findIndex((inp) => inp.inputParam === input.inputParam) - 1];
  if (prevInput) {
    setSelectedInputLevel(prevInput.dependencyLevel);
  } else {
    setSelectedInputLevel(0);
  }

  nextInputs.forEach((nextInput) => {
    if (nextInput.element.type !== 'checkbox') {
      resetInput(nextInput);
    }
  });

  filterInput(input, false);

  nextInputs.forEach((nextInput) => {
    if (nextInput.element.type !== 'checkbox') {
      filterInput(nextInput, false);
    }
  });
}

export function getHighestPrediction(site) {
  const targetPrediction = site.wasRain ? site.predictionWet : site.predictionDry;
  const isSomeNaN = Object.values(targetPrediction).some((value) => isNaN(value));
  const valuesNotZeroes = Object.values(targetPrediction).filter((value) => value > 0).length > 0;

  const highestPrediction = Object.entries(targetPrediction).sort((a, b) => b[1] - a[1])[0][0]; //Get key, where higest percent value
  return isSomeNaN || !valuesNotZeroes ? undefined : highestPrediction;
}

function filterStateOptions() {
  const filterState = getAllFilters();
  const dataState = createDataState();
  const isAdministrative = getIsAdministrative();

  const { county, town, site, organization, category } = filterState;
  const { states, sites } = dataState;

  const filteredStates = [];

  if (isAdministrative) {
    filteredStates.push(
      ...states.filter((state) => {
        if (county && county !== 'none' && !state.counties.some((item) => item === county))
          return false;
        if (site && site !== 'none' && !state.sites.some((item) => item === site)) return false;
        if (town && town !== 'none' && !state.towns.some((item) => item === town)) return false;
        if (
          organization &&
          organization !== 'none' &&
          !state.sites.includes(
            sites
              .filter((site) => state.sites.includes(site.id))
              .find((site) => site.organizations.includes(organization))?.id
          )
        )
          return false;
        if (
          category &&
          category !== 'none' &&
          !state.sites.includes(
            sites
              .filter((site) => state.sites.includes(site.id))
              .find((site) => site.categories.includes(category))?.id
          )
        )
          return false;

        return true;
      })
    );
  } else {
    filteredStates.push(...states);
  }

  return filteredStates.map((item) => {
    const option = document.createElement('option');
    option.classList.add('map_filter-option', 'map_filter-option--states');
    option.value = item.id;
    option.textContent = item.name;
    return option;
  });
}

