function filterTagOptions({ targetKey, membershipKey, crossKey, isRequired }) {
  const filterState = getAllFilters();
  const data = createDataState();

  const { sites, states, counties, towns, watersheds, waterbodies } = data;

  const targetCollection = data[targetKey];

  const siteById = new Map(sites.map((s) => [s.id, s]));

  const singleRefFilters = [
    { key: 'state', collection: states },
    { key: 'county', collection: counties },
    { key: 'town', collection: towns },
    { key: 'watershed', collection: watersheds },
    { key: 'waterbody', collection: waterbodies },
  ];

  function intersect(a, b) {
    if (!a) return b;
    const set = new Set(b);
    return a.filter((id) => set.has(id));
  }

  let candidateSiteIds = null;

  for (const filter of singleRefFilters) {
    const val = filterState[filter.key];
    if (val && val !== 'none') {
      const matchedItem = filter.collection.find((item) => item.id === val);
      if (!matchedItem) return [];
      candidateSiteIds = intersect(candidateSiteIds, matchedItem.sites || []);
      if (candidateSiteIds.length === 0) return [];
    }
  }

  if (crossKey && filterState[crossKey] && filterState[crossKey] !== 'none') {
    const crossCollection = crossKey === 'category' ? data.categories : data.organizations;
    const crossMatched = crossCollection.find((item) => item.id === filterState[crossKey]);
    if (!crossMatched) return [];
    candidateSiteIds = intersect(candidateSiteIds, crossMatched.sites || []);
    if (candidateSiteIds.length === 0) return [];
  }

  if (filterState.site && filterState.site !== 'none') {
    const s = siteById.get(filterState.site);
    if (!s) return [];
    candidateSiteIds = intersect(candidateSiteIds, [s.id]);
    if (candidateSiteIds.length === 0) return [];
  }

  if (!candidateSiteIds) candidateSiteIds = sites.map((s) => s.id);

  function anySiteLinksTo(targetId) {
    for (const siteId of candidateSiteIds) {
      const site = siteById.get(siteId);
      if (site?.[membershipKey]?.includes(targetId)) return true;
    }
    return false;
  }

  const filtered = targetCollection.filter((item) => anySiteLinksTo(item.id));

  return toOptions(filtered, targetKey);
}

function filterOrganizationOptions() {
  return filterTagOptions({
    targetKey: 'organizations',
    membershipKey: 'organizations',
    crossKey: 'category',
  });
}

function filterCategoriesOptions() {
  return filterTagOptions({
    targetKey: 'categories',
    membershipKey: 'categories',
    crossKey: 'organization',
  });
}

function filterSitesOptions() {
  return filterSites().map((item) => {
    const option = document.createElement('option');
    option.classList.add('map_filter-option', 'map_filter-option--sites');
    option.value = item.id;
    option.textContent = item.name;
    return option;
  });
}

function getSortedInputsByDependency(inputs = filtersInputs, reverse = false) {
  const inputsCopy = [...inputs];
  return reverse
    ? inputsCopy.sort((a, b) => b.dependencyLevel - a.dependencyLevel)
    : inputsCopy.sort((a, b) => a.dependencyLevel - b.dependencyLevel);
}

function getNextInputs(dependencyLevel) {
  return filtersInputs.filter((item) => item.dependencyLevel > dependencyLevel);
}

function getPrevInputs(dependencyLevel) {
  return filtersInputs.filter((item) => item.dependencyLevel < dependencyLevel);
}

function enableResetBtn(input) {
  const resetBtn = document.querySelector(`#reset-filter-${input.inputParam}`);
  if (resetBtn) {
    resetBtn.classList.add('is--active');
  } else {
    console.warn(`Not found #reset-filter-${input.inputParam} reset button`);
  }
}

function disableResetBtn(input) {
  const resetBtn = document.querySelector(`#reset-filter-${input.inputParam}`);
  if (resetBtn) {
    resetBtn.classList.remove('is--active');
  } else {
    console.warn(`Not found #reset-filter-${input.inputParam} reset button`);
  }
}

