const { getIsOutlook } = useTabsStore.getState();
const { getLang, getAccessibility, setDrawnBoundaryType, setDrawnBoundaryId } =
  useDataStore.getState();
const { setSitesFeatures, getSiteFeatures, setFeaturesProps, getFeaturesProps } =
  useFeaturesStore.getState();
const sitePopupClass = 'site-popup';
const measurmentsClass = 'site-popup_measurements';

let lastDrawnFeatureId = null;
let currentHightlightedId = null;
let currentlyHoveredId = null;
let hoverPopup = null;
let activeSitePopup = null;
const mapUpdatesQueue = [];
const imageBarQueue = [];
const initializedSources = {};
const mapView = document.querySelector('.map_view-wrapper');
mapView.setAttribute('tabindex', '1');
const originalFocus = HTMLElement.prototype.focus;

async function addDynamicMarkerIcon(iconId) {
  const svgUrl = icons.get(iconId);
  const ratio = Math.max(1, Math.min(window.devicePixelRatio || 1, 3));
  const img = await new Promise((resolve, reject) => {
    const el = new Image();
    el.decoding = 'async';
    el.onload = () => resolve(el);
    el.onerror = reject;
    el.src = svgUrl;
  });

  let w = img.naturalWidth;
  let h = img.naturalHeight;

  if (!w || !h) {
    try {
      const [, base64] = svgUrl.split(',');
      const svgText = decodeURIComponent(atob(base64));
      const m = svgText.match(
        /viewBox\s*=\s*["']\s*([\d.]+)\s+([\d.]+)\s+([\d.]+)\s+([\d.]+)\s*["']/i
      );
      if (m) {
        w = parseFloat(m[3]);
        h = parseFloat(m[4]);
      }
    } catch (_) {}
  }

  if (!w || !h) {
    w = 64;
    h = 64;
  }

  const targetW = Math.round(w * ratio);
  const targetH = Math.round(h * ratio);

  const canvas = document.createElement('canvas');
  canvas.width = targetW;
  canvas.height = targetH;
  const ctx = canvas.getContext('2d');
  ctx.drawImage(img, 0, 0, targetW, targetH);

  const bitmap = await createImageBitmap(canvas);

  if (map.hasImage(iconId)) map.removeImage(iconId);
  map.addImage(iconId, bitmap, { pixelRatio: ratio });
}

async function addAllIconsToMap() {
  const timer = new Date().getTime();
  for (const [id, url] of icons) {
    if (id.startsWith('marker')) await addDynamicMarkerIcon(id);
  }
}

async function createMarkerLayer(data, isZoom = true) {
  const access = getAccessibility();
  // console.log('Data length: ', data.length);
  const featuresProps = {};
  const features = data.map((site) => {
    const siteType = getSiteType(site);

    featuresProps[site.id] = {
      id: site.id,
      name: site.name,
      wasRain: site.wasRain,
      date: site.date,
      predictionWet: site.predictionWet,
      predictionDry: site.predictionDry,
      quality: siteType.quality,
      qualityValue: site.quality,
      relevance: siteType.relevance,
      state: site.state,
      county: site.county,
      town: site.town,
      watershed: site.watershed,
      waterbody: site.waterbody,
      latitude: site.latitude,
      longitude: site.longitude,
      slug: site.slug,
      image: site.image,
    };

    return {
      type: 'Feature',
      geometry: {
        type: 'Point',
        coordinates: [site.longitude, site.latitude],
      },
      id: site.id,
      properties: {
        id: site.id,
        icon: `marker-${siteType.quality}-${siteType.relevance}${access ? '-access' : ''}`,
        originalIcon: `marker-${siteType.quality}-${siteType.relevance}${access ? '-access' : ''}`,
        iconScale: 1,
      },
    };
  });

  const featuresMap = new Map();
  features.forEach((feature) => {
    featuresMap.set(feature.id, feature);
  });

  setSitesFeatures(featuresMap);
  setFeaturesProps(featuresProps);

  async function addMarkers() {
    await addAllIconsToMap();

    if (!map.getSource('site-points')) {
      // console.log('First add source: ', features.length);
      map.addSource('site-points', {
        type: 'geojson',
        data: {
          type: 'FeatureCollection',
          features,
        },
        promoteId: 'id',
      });
    }

    if (!map.getLayer('site-points-layer')) {
      //Icons layer
      // console.log('First add site-points layer');
      map.addLayer({
        id: 'site-points-layer',
        type: 'symbol',
        source: 'site-points',
        layout: {
          'icon-image': ['get', 'icon'],
          'icon-size': ['get', 'iconScale'],
          'icon-anchor': 'bottom',
          'icon-allow-overlap': true,
          'icon-ignore-placement': true,
        },
      });

      if (isZoom) zoomToFilteredSites(data);

      // Add popup on click
      map.on('click', 'site-points-layer', (e) => {
        const isMobile = window.innerWidth <= 767;
        const isTouch = window.matchMedia && window.matchMedia('(pointer: coarse)').matches;

        const featuresProps = getFeaturesProps();
        const featureId = e.features[0].properties.id;
        const props = featuresProps[featureId];
        const mapContainer = map.getCanvas();

        const popupHtml = formatSitePopup(props);

        const pixel = map.project([props.longitude, props.latitude]);

        const { anchor, offset } = getPopupAnchorAndOffset(pixel, props.relevance);

        // console.log(`offset:`);
        // console.log(offset);

        new mapboxgl.Popup({ anchor: isMobile ? 'bottom' : anchor })
          .setLngLat([props.longitude, props.latitude])
          .setOffset(offset)
          .setHTML(popupHtml)
          .addTo(map);

        activeSitePopup = { ...props };

        const sitePopup = document.querySelector(`.${sitePopupClass}`);
        const popupTextWrapper = document.querySelector(`.site-popup_text-wrapper`);
        const popupWrapper = document.querySelector(`.mapboxgl-popup-content:has(.site-popup)`);

        if (popupTextWrapper && popupWrapper) {
          const popupHeight =
            popupTextWrapper.scrollHeight + (props.image ? (isMobile ? 120 : 80) : 0);

          if (anchor.startsWith('top') && !isMobile)
            popupWrapper.style.clipPath = 'inset(0 0 100% 0)';
          else popupWrapper.style.clipPath = 'inset(100% 0 0 0)';

          popupWrapper.style.height = `${popupHeight}px`;

          gsap.to(popupWrapper, {
            clipPath: 'inset(0% 0% 0% 0%)',
            duration: 0.3,
            ease: 'power1.out',
          });

          const measurments = sitePopup.querySelector(`.${measurmentsClass}`);
          if (measurments)
            gsap.to(measurments, {
              width: '100%',
              duration: 0.5,
              ease: 'power1.out',
            });

          sitePopup.classList.add(`${sitePopupClass}--active`);
        }

        if (isTouch) {
          const feature = e.features?.[0];
          const newId = feature?.id;
          if (newId !== currentlyHoveredId) {
            if (currentlyHoveredId !== null) {
              unhighlightMapSite(currentlyHoveredId);
            }
            if (newId !== null && newId !== undefined) {
              highlightMapSite(newId, feature);
            }
            currentlyHoveredId = newId;
          }
        }

        const closeBtn = document.querySelector('.mapboxgl-popup-close-button');

        const clearActivePopupState = (e) => {
          const popupEl = document.querySelector('.mapboxgl-popup-content');
          if (popupEl && popupEl.contains(e.target)) {
            return;
          }

          if (isTouch) {
            unhighlightMapSite(currentlyHoveredId);
            currentlyHoveredId = null;
          }

          activeSitePopup = null;
          mapContainer.removeEventListener('click', clearActivePopupState);
          closeBtn.removeEventListener('click', clearActivePopupState);
        };

        mapContainer.addEventListener('click', clearActivePopupState);
        closeBtn.addEventListener('click', clearActivePopupState);
      });

      map.on('mousemove', 'site-points-layer', (e) => {
        const isTouch = window.matchMedia && window.matchMedia('(pointer: coarse)').matches;
        if (!isTouch) {
          map.getCanvas().style.cursor = 'pointer';

          const feature = e.features?.[0];
          const newId = feature?.id;

          if (newId !== currentlyHoveredId) {
            if (currentlyHoveredId !== null) {
              unhighlightMapSite(currentlyHoveredId);
            }
            if (newId !== null && newId !== undefined) {
              highlightMapSite(newId, feature);
            }
            currentlyHoveredId = newId;
          }
        }
      });

      map.on('mouseleave', 'site-points-layer', (e) => {
        const isTouch = window.matchMedia && window.matchMedia('(pointer: coarse)').matches;
        if (!isTouch) {
          map.getCanvas().style.cursor = '';
          if (currentlyHoveredId !== null) {
            unhighlightMapSite(currentlyHoveredId);
            currentlyHoveredId = null;
          }
        }
      });
    }
  }

  await addMarkers();
}

function updateMarkers(sites, isZoom) {
  const access = getAccessibility();
  const featuresProps = {};
  const newFeatures = sites.map((site) => {
    const siteType = getSiteType(site);
    featuresProps[site.id] = {
      name: site.name,
      wasRain: site.wasRain,
      date: site.date,
      predictionWet: site.predictionWet,
      predictionDry: site.predictionDry,
      quality: siteType.quality,
      qualityValue: site.quality,
      relevance: siteType.relevance,
      watershed: site.watershed,
      waterbody: site.waterbody,
      state: site.state,
      county: site.county,
      town: site.town,
      latitude: site.latitude,
      longitude: site.longitude,
      image: site.image,
      slug: site.slug,
    };
    return {
      type: 'Feature',
      geometry: {
        type: 'Point',
        coordinates: [site.longitude, site.latitude],
      },
      id: site.id,
      properties: {
        id: site.id,
        icon: `marker-${siteType.quality}-${siteType.relevance}${access ? '-access' : ''}`,
        originalIcon: `marker-${siteType.quality}-${siteType.relevance}${access ? '-access' : ''}`,
        iconScale: 1,
      },
    };
  });

  const featuresMap = new Map();
  newFeatures.forEach((feature) => {
    featuresMap.set(feature.id, feature);
  });

  setSitesFeatures(featuresMap);
  setFeaturesProps(featuresProps);

  waitForSourceAndUpdate('site-points', updateSourceData);

  function updateSourceData() {
    // console.log('Update sorce data: ', newFeatures.length);
    map.getSource('site-points').setData({
      type: 'FeatureCollection',
      features: newFeatures,
    });

    if (isZoom) zoomToFilteredSites(sites);

    if (sites.length === 0)
      waitForFeaturesRendered('site-points', () => {
        map.fire('manualUpdate');
      });
  }
}

//For filters,tabs,map initialization
function waitForSourceAndUpdate(sourceId, callback) {
  if (!initializedSources[sourceId] && initializedSources[sourceId] !== false)
    initializedSources[sourceId] = false;

  if (isReady()) {
    // console.log('waitForSourceAndUpdate Is ready');
    initializedSources[sourceId] = true;
    callback();
    return;
  }

  mapUpdatesQueue.push(callback);

  function isReady() {
    return initializedSources[sourceId] || map.getSource(sourceId);
  }

  function done() {
    // console.log('waitForSourceAndUpdate - done');
    initializedSources[sourceId] = true;
    map.off('sourcedata', onSourceData);

    const queue = [...mapUpdatesQueue];
    mapUpdatesQueue.length = 0;

    for (const fn of queue) fn();
  }

  function onSourceData(e) {
    if (e.sourceId === sourceId && isReady()) {
      done();
    }
  }

  map.on('sourcedata', onSourceData);
}

//For image-bar
function waitForFeaturesRendered(sourceId, callback) {
  function getOnMapFeatures() {
    const bounds = map.getBounds();
    const topLeft = map.project(bounds.getNorthWest());
    const bottomRight = map.project(bounds.getSouthEast());
    const pixelBounds = [
      [topLeft.x, topLeft.y],
      [bottomRight.x, bottomRight.y],
    ];
    const features = [
      ...map.queryRenderedFeatures(pixelBounds, {
        layers: ['site-points-layer'],
      }),
    ];
    return features;
  }

  if (isReady()) {
    const features = getOnMapFeatures();
    if (features > 0) {
      // console.log('waitForFeaturesRendered Is ready');

      callback(features);
      return;
    }
  }

  // console.log('waitForFeaturesRendered Is NOT ready');
  imageBarQueue.push(callback);

  function isReady() {
    return map.getSource(sourceId) && map.isSourceLoaded(sourceId) && map.isStyleLoaded();
  }

  function done() {
    // console.log('waitForFeaturesRendered - done');
    map.off('idle', onIdle);
    const features = getOnMapFeatures();

    const queue = [...imageBarQueue];
    imageBarQueue.length = 0;

    for (const fn of queue) fn(features);
  }

  function onIdle() {
    if (isReady()) {
      done();
    }
  }

  map.on('idle', onIdle);
}

function updateBoundaryOutline({
  checkPoints,
  boundaryId,
  boundaryType,
  clearOnly = false,
  force = false,
}) {
  const sourceId = 'highlighted-feature';
  const layerId = 'highlighted-feature-outline';

  if (clearOnly) {
    if (map.getLayer(layerId)) map.removeLayer(layerId);
    if (map.getSource(sourceId)) map.removeSource(sourceId);
    setDrawnBoundaryType(undefined);
    setDrawnBoundaryId(undefined);
    lastDrawnFeatureId = null;
    return;
  }

  if (!checkPoints || checkPoints.length === 0) return;

  let matchedFeature = null;

  for (const point of checkPoints) {
    matchedFeature = findBoundary({
      boundaryType,
      boundaryId,
      latitude: point.latitude,
      longitude: point.longitude,
    });
    if (matchedFeature || matchedFeature === false) break;
  }

  if (!matchedFeature) {
    // console.log(
    //   `${isBoundariesLoaded ? `No matching boundary found for ${boundaryType}, zooming to points` : `Boundaries still downloading, zooming to points`}`
    // );
    zoomToFilteredSites(checkPoints);
    return;
  }

  const featureId =
    matchedFeature?.id || matchedFeature?.properties?.id || JSON.stringify(matchedFeature);

  if (featureId === lastDrawnFeatureId && !force) {
    map.fire('manualUpdate');
    if (boundaryType === 'waterbody') zoomToFilteredSites(checkPoints);
    return;
  }

  if (map.getLayer(layerId)) map.removeLayer(layerId);
  if (map.getSource(sourceId)) map.removeSource(sourceId);

  try {
    map.addSource(sourceId, {
      type: 'geojson',
      data: matchedFeature,
    });

    setDrawnBoundaryType(boundaryType);
    setDrawnBoundaryId(boundaryId);
    lastDrawnFeatureId = featureId;
  } catch (error) {
    console.error(`Error with boundary file ${boundaryId}`);
    zoomToFilteredSites(checkPoints);
  }

  map.addLayer(
    {
      id: layerId,
      type: 'line',
      source: sourceId,
      paint: {
        'line-color': '#FF5733',
        'line-width': 1,
        'line-opacity': 0,
      },
    },
    'site-points-layer'
  );

  map.setPaintProperty(layerId, 'line-opacity-transition', {
    duration: 1250,
    delay: 0,
  });
  map.setPaintProperty(layerId, 'line-opacity', 1);

  try {
    if (boundaryType !== 'waterbody') zoomToFilteredFeature(matchedFeature);
    else zoomToFilteredSites(checkPoints);
  } catch (error) {
    console.error(`Error with boundary file ${boundaryId}`);
    zoomToFilteredSites(checkPoints);
  }
}

function rebuildPopup() {
  const popup = document.querySelector(`.${sitePopupClass}`);
  if (
    !popup ||
    !activeSitePopup ||
    (activeSitePopup.wasRain &&
      Object.values(activeSitePopup.predictionWet).filter((value) => value > 0).length === 0) ||
    (!activeSitePopup.wasRain &&
      Object.values(activeSitePopup.predictionDry).filter((value) => value > 0).length === 0)
  )
    return;

  const tween = gsap.to(popup, {
    opacity: 0,
    duration: 0.3,
    ease: 'power1.out',
  });

  tween.eventCallback('onComplete', () => {
    const newPopup = htmlToElement(formatSitePopup(activeSitePopup));
    newPopup.classList.add(`${sitePopupClass}--active`);
    newPopup.style.opacity = 0;
    popup.replaceWith(newPopup);

    gsap.to(newPopup, {
      opacity: 1,
      duration: 0.3,
      ease: 'power1.out',
    });

    const measurments = newPopup.querySelector(`.${measurmentsClass}`);
    if (measurments)
      gsap.to(measurments, {
        width: '100%',
        duration: 0.5,
        ease: 'power1.out',
      });
  });
}

function formatSitePopup(site) {
  // console.log(`Format site: `);
  // console.log(site);
  const lang = getLang();
  const access = getAccessibility();
  // console.log(lang);

  const isMobile = window.innerWidth <= 767;

  const outlookHtml = lang === 'es' ? popupOutlookEsHtml : popupOutlookHtml;
  const generalHtml = lang === 'es' ? popupGeneralEsHtml : popupGeneralHtml;
  const noDataHtml = lang === 'es' ? popupNoDataEsHtml : popupNoDataHtml;

  const colors = {
    clean: 'var(--color--water-main)',
    boat: 'var(--color--sand-main)',
    notClean: 'var(--color--buoy-main)',
  };

  const formatter = new Intl.DateTimeFormat('en-US', {
    day: '2-digit',
    month: 'short',
    year: 'numeric',
  });

  const siteType = getSiteType(site);
  const isOutlook = getIsOutlook();

  const popupHtml =
    isOutlook && getHighestPrediction(site) ? outlookHtml : site.date ? generalHtml : noDataHtml;
  let predictionSortedEntries;
  let predictionText;
  if (getHighestPrediction(site)) {
    predictionSortedEntries = calculatePredictionPercentages(
      Object.entries(getTargetPrediction(site)).sort((a, b) => b[1] - a[1])
    );
    predictionSortedEntries = formatPercentages(predictionSortedEntries);
    predictionText = generateTextPrediction(predictionSortedEntries);
  }

  if (isMobile) {
    HTMLElement.prototype.focus = function () {};
    requestAnimationFrame(() => {
      HTMLElement.prototype.focus = originalFocus;
    });
  }

  return popupHtml
    .replace('SITE_NAME', site.name)
    .replace(
      'IMG',
      site.image
        ? `<a href="${window.location.origin}${lang !== 'en' ? `/${lang}` : ''}/sites/${site.slug}"  class="site-popup_image-wrapper"><img class="popup-image" src="${site.image}" alt="site image" /></a>`
        : ''
    )
    .replace('SITE_PREDICTION', predictionText)
    .replace('SITE_QUALITY', getSiteQuality(site))
    .replace('QUALITY_GENERAL_COLOR', colors[siteType.quality])
    .replace('LAST_SAMPLE_TAKEN', formatter.format(site.date))
    .replace('LAST_SAMPLE_VALUE', `${site.qualityValue} MPN/100mL`)
    .replace('FIRST_MEASURE_WIDTH', `calc(${predictionSortedEntries?.[0]?.[1]}% - 4px)`)
    .replace('FIRST_MEASURE_COLOR', colors[predictionSortedEntries?.[0]?.[0]])
    .replace('SECOND_MEASURE_WIDTH', `${predictionSortedEntries?.[1]?.[1]}%`)
    .replace('SECOND_MEASURE_COLOR', colors[predictionSortedEntries?.[1]?.[0]])
    .replace('THIRD_MEASURE_WIDTH', `${predictionSortedEntries?.[2]?.[1]}%`)
    .replace('THIRD_MEASURE_COLOR', colors[predictionSortedEntries?.[2]?.[0]])
    .replaceAll(
      'SITE_LINK',
      `${window.location.origin}${lang !== 'en' ? `/${lang}` : ''}/sites/${site.slug}`
    );
}

function getTargetPrediction(site) {
  return site.wasRain ? site.predictionWet : site.predictionDry;
}

function getSiteQuality(site) {
  const lang = getLang();

  const textVariants = {
    en: {
      clean: 'Clean for swimming',
      boat: 'Clean for boating only',
      notClean: 'Not clean',
      chance: 'chance',
    },
    es: {
      clean: 'Limpio para nadar',
      boat: 'Limpio solo para navegación',
      notClean: 'No limpio',
      chance: 'de posibilidades',
    },
  };

  const siteType = getSiteType(site);
  const phrase = textVariants[lang][siteType.quality];

  return phrase;
}

function generateTextPrediction(predictionEntries) {
  const lang = getLang();

  const textVariants = {
    en: {
      clean: 'Clean for swimming',
      boat: 'Clean for boating only',
      notClean: 'Not clean',
      chance: 'chance',
    },
    es: {
      clean: 'Limpio para nadar',
      boat: 'Limpio solo para navegación',
      notClean: 'No limpio',
      chance: 'de posibilidades',
    },
  };

  const [quality, probability] = predictionEntries[0];
  const langTexts = textVariants[lang] || textVariants.en;

  const phrase = langTexts[quality] || ['Unknown'];
  const chanceText = langTexts.chance;

  return `${phrase} (${Math.floor(probability)}% ${chanceText})`;
}

function calculatePredictionPercentages(predictionEntries) {
  const percentageSum = predictionEntries.reduce((acc, curr) => {
    const accVal = Array.isArray(acc) ? acc[1] : acc;
    return accVal + curr[1];
  });
  const multiplier = 100 / percentageSum;
  return predictionEntries.map((entry) => [entry[0], entry[1] * multiplier]);
}

function formatPercentages(predictionEntries) {
  const newEntries = [...predictionEntries];
  newEntries.forEach(([key, value], index) => {
    if (value === 100) {
      if (index - 1 < 0) newEntries[index + 1][1] += 1;
      else newEntries[index - 1][1] += 1;

      newEntries[index][1] = 99;
    }

    if (value === 0) {
      const maxIndex = findMaxIndex(Object.values(Object.fromEntries(newEntries)));
      newEntries[maxIndex][1] -= 1;
      newEntries[index][1] += 1;
    }
  });

  return newEntries;

  function findMaxIndex(arr) {
    let max = 0;
    let maxIndex = 0;
    arr.forEach((value, index) => {
      if (max < value) {
        max = value;
        maxIndex = index;
      }
    });
    return maxIndex;
  }
}

function zoomToFilteredFeature(feature) {
  const boudaryBox = bbox(feature);

  const bounds = new mapboxgl.LngLatBounds(
    [boudaryBox[0], boudaryBox[1]],
    [boudaryBox[2], boudaryBox[3]]
  );

  map.fitBounds(bounds, {
    padding: {
      top: 50,
      left: 50,
      right: 50,
      bottom: 183,
    },
    duration: 800,
    maxZoom: 12,
  });
}

function zoomToFilteredSites(sites) {
  if (!sites.length) return;

  const coordinates = sites.map((site) => [site.longitude, site.latitude]);
  const bounds = new mapboxgl.LngLatBounds();

  coordinates.forEach((coord) => bounds.extend(coord));

  map.fitBounds(bounds, {
    padding: {
      top: 50,
      left: 50,
      right: 50,
      bottom: 183,
    },
    duration: 800,
    maxZoom: 14,
  });
}

function getSiteType(site) {
  if (!site) {
    console.error('Site is required parameter');
    return;
  }
  const type = {
    relevance: '',
    quality: '',
  };
  const isOutlook = getIsOutlook();
  const month = 1000 * 60 * 60 * 24 * 30;
  const year = 1000 * 60 * 60 * 24 * 365;

  if (!site.date) {
    type.relevance = 'old';
  } else {
    const difference = Date.now() - site.date.getTime();
    if (difference < month) type.relevance = 'month';
    if (difference > month && difference < year) type.relevance = 'year';
    if (!type.relevance) type.relevance = 'old';
  }
  const prediction = getHighestPrediction(site);

  if (isOutlook && prediction) {
    type.quality = prediction;
  } else {
    const clearColiValue = 235;
    const boatingColiValue = 575;
    const quality = typeof site.quality === 'string' ? site.qualityValue : site.quality;
    if (quality < clearColiValue) type.quality = 'clean';
    if (quality > clearColiValue && quality < boatingColiValue) type.quality = 'boat';
    if (!type.quality) type.quality = 'notClean';
  }

  return type;
}

function animateMarkerScale(featureId, toSize) {
  const features = getSiteFeatures();
  const match = features.get(featureId);

  //It's ok, if user zooms to some area and image-bar automaticly unhightlight all markers
  if (!match && toSize === 1) {
    return;
  }

  if (!match) {
    console.warn(`Not found feature with id ${featureId} in animateMarkerScale`);
    return;
  }

  //Hightlight marker
  const originalIcon = match.properties.originalIcon;
  const targetIcon = toSize === 1 ? originalIcon : `${originalIcon}-hightlighted`;

  const updatedFeaturesMap = new Map(features);
  updatedFeaturesMap.set(featureId, {
    ...match,
    properties: { ...match.properties, icon: targetIcon },
  });
  map.getSource('site-points').setData({
    type: 'FeatureCollection',
    features: Array.from(updatedFeaturesMap.values()),
  });
  setSitesFeatures(updatedFeaturesMap);
}

function highlightMapSite(siteId, feature) {
  const isMobile = window.innerWidth <= 767;
  if (isMobile) {
    if (mapView) {
      HTMLElement.prototype.focus = originalFocus;
      mapView.focus();
    }
  }
  if (currentHightlightedId && currentHightlightedId !== siteId) {
    animateMarkerScale(siteId, 1);
    destroyHoverPopup();
  }

  if (!activeSitePopup) makeHoverPopup(feature);
  animateMarkerScale(siteId, 1.5);
  currentHightlightedId = siteId;
}

function getPopupAnchorAndOffset(pixel, relevance) {
  const { clientWidth, clientHeight } = map.getCanvas();

  const verticalYValues = { top: 3, bottom: -40 };

  if (relevance === 'old') {
    verticalYValues.bottom = -20;
  }

  const vertical =
    pixel.y < clientHeight * 0.33 ? 'top' : pixel.y > clientHeight * 0.66 ? 'bottom' : '';
  const horizontal =
    pixel.x < clientWidth * 0.33 ? 'left' : pixel.x > clientWidth * 0.66 ? 'right' : '';

  const anchor =
    vertical && horizontal ? `${vertical}-${horizontal}` : vertical || horizontal || 'bottom';

  const offsetY =
    vertical === 'top'
      ? verticalYValues.top
      : vertical === 'bottom'
        ? verticalYValues.bottom
        : verticalYValues.bottom;
  const offsetX = horizontal === 'left' ? 20 : horizontal === 'right' ? -20 : 0;

  return {
    anchor,
    offset: [offsetX, offsetY],
  };
}

function makeHoverPopup(feature) {
  const coordinates = feature?.geometry?.coordinates || [feature.longitude, feature.latitude];
  if (feature) {
    const props = getFeaturesProps()[feature.id];
    if (!props) return;

    const pixel = map.project(coordinates);
    const { anchor, offset } = getPopupAnchorAndOffset(pixel, props.relevance);

    if (!hoverPopup) {
      hoverPopup = new mapboxgl.Popup({
        closeButton: false,
        closeOnClick: false,
        className: 'hover-popup',
        anchor,
      });
    }

    hoverPopup
      .setLngLat(coordinates)
      .setHTML(`<span class="hover-popup">${props.name}</span>`)
      .setOffset(offset)
      .addTo(map);
  } else {
    console.error('Cannot create hover popup without feature');
  }
}

function destroyHoverPopup() {
  if (hoverPopup) {
    hoverPopup.remove();
    hoverPopup = null;
  }
}

function unhighlightMapSite(siteId = currentHightlightedId) {
  if (siteId) {
    destroyHoverPopup();
    animateMarkerScale(siteId, 1);
  } else {
    console.warn('Unexpected null in unhighlightMapSite');
  }
}

export {
  rebuildPopup,
  createMarkerLayer,
  updateMarkers,
  updateBoundaryOutline,
  highlightMapSite,
  unhighlightMapSite,
  getSiteType,
  waitForSourceAndUpdate,
  waitForFeaturesRendered,
};
