import { useDataStore } from '../store/data-store';
import { filterSites } from './filter';
import { createMarkerLayer, updateBoundaryOutline } from './markers';

const { getMapStyle, setMapStyle, getDrawnBoundaryId, getDrawnBoundaryType } =
  useDataStore.getState();

export default class MapStyleControll {
  onAdd(map) {
    this.map = map;

    this.container = document.createElement('div');
    this.container.className = 'mapboxgl-ctrl mapboxgl-ctrl-group';

    const className = 'mapboxgl-ctrl-map-style';
    const activeClassName = 'mapboxgl-ctrl-map-style--active';

    const button = document.createElement('button');
    button.type = 'button';

    const icon = document.createElement('span');
    icon.classList.add('mapboxgl-ctrl-icon');

    button.classList.add(className);
    button.setAttribute('aria-label', 'Toggle Accessibility Mode');

    button.append(icon);

    const defaultMapStyle = 'mapbox://styles/rodonnell-ctriver/cme050tqw018g01qpa23h8jj3';
    const satelliteMapStyle = 'mapbox://styles/mapbox/satellite-v9';

    button.addEventListener('click', () => {
      const boundaryType = getDrawnBoundaryType();
      const boundaryId = getDrawnBoundaryId();
      const mapStyle = getMapStyle();
      let targetMapStyle;
      if (mapStyle === defaultMapStyle) {
        targetMapStyle = satelliteMapStyle;
      } else {
        targetMapStyle = defaultMapStyle;
      }

      const sites = filterSites();
      map.setStyle(targetMapStyle);
      setMapStyle(targetMapStyle);

      const onStyleLoad = async () => {
        await createMarkerLayer(sites, false);
        if (boundaryId || boundaryType)
          updateBoundaryOutline({ checkPoints: sites, boundaryId, boundaryType, force: true });
        button.classList.toggle(activeClassName);
        map.off('style.load', onStyleLoad);
      };

      map.on('style.load', onStyleLoad);
    });

    this.container.appendChild(button);
    return this.container;
  }

  onRemove() {
    this.container.parentNode.removeChild(this.container);
    this.map = undefined;
  }
}
