import { useDataStore } from '../store/data-store';
import { updateMarkers } from './markers';
import { map } from './maploader';
import { filterSites } from './filter';
import { updateIconsByAccess } from './build-sites-nearby';

const { toggleAccessibility, getAccessibility } = useDataStore.getState();

const elementAccessClasses = [
  'mapboxgl-ctrl-access',
  'mapboxgl-ctrl-fullscreen',
  'mapboxgl-ctrl-shrink',
  'mapboxgl-ctrl-map-style',
];

function handleAccess() {
  const accessBtn = document.querySelector('#accessibility');
  if (accessBtn) accessBtn.addEventListener('click', updateAccess);

  const accessibility = getAccessibility();
  if (accessibility) {
    toggleControllAccessCollors();
  }
}

function updateAccess() {
  toggleAccessibility();
  toggleControllAccessCollors();
  updateStaticIcons();
  const sites = filterSites();
  updateMarkers(sites);
  map.fire('manualUpdate');
}

function updateStaticIcons() {
  updateIconsByAccess();
}

function toggleControllAccessCollors() {
  elementAccessClasses.forEach((className) => {
    const element = document.querySelector(`.${className}`);
    if (element) {
      if (className === 'mapboxgl-ctrl-fullscreen') {
        element.classList.toggle(`mapboxgl-ctrl-shrink--access`);
      } else {
        element.classList.toggle(`${className}--access`);
      }
    }
  });
}

export { handleAccess, updateAccess };
