import { createStore } from 'zustand/vanilla';

export const initialFiltersState = {
  state: '',
  county: '',
  town: '',
  watershed: '',
  waterbody: '',
  organization: '',
  category: '',
  site: '',
  clean: false,
  boating: false,
  notClean: false,
  month: false,
  year: false,
  old: false,
};

if (!window.__GLOBAL_FILTERS_STORE__) {
  window.__GLOBAL_FILTERS_STORE__ = createStore((set, get) => ({
    selectedFilters: { ...initialFiltersState },
    selectedInputLevel: undefined,
    inputHandlers: [], // This will be used to track the currently selected filter level and provide dependency logic

    setStateFilter: (stateFilter) =>
      set((state) => ({ selectedFilters: { ...state.selectedFilters, state: stateFilter } })),
    setCountyFilter: (county) =>
      set((state) => ({ selectedFilters: { ...state.selectedFilters, county } })),
    setTownFilter: (town) =>
      set((state) => ({ selectedFilters: { ...state.selectedFilters, town } })),
    setWaterShedFilter: (watershed) =>
      set((state) => ({ selectedFilters: { ...state.selectedFilters, watershed } })),
    setWaterBodyFilter: (waterbody) =>
      set((state) => ({ selectedFilters: { ...state.selectedFilters, waterbody } })),
    setOrganizationFilter: (organization) =>
      set((state) => ({ selectedFilters: { ...state.selectedFilters, organization } })),
    setSiteFilter: (site) =>
      set((state) => ({ selectedFilters: { ...state.selectedFilters, site } })),
    setCleanFilter: (clean) =>
      set((state) => ({ selectedFilters: { ...state.selectedFilters, clean } })),
    setBoatingFilter: (boating) =>
      set((state) => ({ selectedFilters: { ...state.selectedFilters, boating } })),
    setCategoryFilter: (category) =>
      set((state) => ({ selectedFilters: { ...state.selectedFilters, category } })),
    setNotCleanFilter: (notClean) =>
      set((state) => ({ selectedFilters: { ...state.selectedFilters, notClean } })),
    setYearFilter: (year) =>
      set((state) => ({ selectedFilters: { ...state.selectedFilters, year } })),
    setMonthFilter: (month) =>
      set((state) => ({ selectedFilters: { ...state.selectedFilters, month } })),
    setOldFilter: (old) => set((state) => ({ selectedFilters: { ...state.selectedFilters, old } })),
    setSelectedInputLevel: (level) =>
      set((state) => ({ selectedFilters: state.selectedFilters, selectedInputLevel: level })),
    pushInputHandler: (handler) =>
      set((state) => ({ inputHandlers: [...state.inputHandlers, handler] })),
    clearInputHandlers: () => set(() => ({ inputHandlers: [] })),
    clearWaterFilters: () =>
      set((state) => ({
        selectedFilters: { ...state.selectedFilters, watershed: '', waterbody: '' },
      })),
    clearAdminFilters: () =>
      set((state) => ({
        selectedFilters: { ...state.selectedFilters, state: '', county: '', town: '' },
      })),

    getStateFilter: () => get().selectedFilters.state,
    getCountyFilter: () => get().selectedFilters.county,
    getTownFilter: () => get().selectedFilters.town,
    getWaterShedFilter: () => get().selectedFilters.watershed,
    getWaterBodyFilter: () => get().selectedFilters.waterbody,
    getOrganizationFilter: () => get().selectedFilters.organization,
    getSiteFilter: () => get().selectedFilters.site,
    getCategoryFilter: () => get().selectedFilters.category,
    getCleanFilter: () => get().selectedFilters.clean,
    getBoatingFilter: () => get().selectedFilters.boating,
    getNotCleanFilter: () => get().selectedFilters.notClean,
    getYearFilter: () => get().selectedFilters.year,
    getMonthFilter: () => get().selectedFilters.month,
    getSelectedInputLevel: () => get().selectedInputLevel,
    getOldFilter: () => get().selectedFilters.old,
    getAllFilters: () => get().selectedFilters,
    getInputHandlers: () => get().inputHandlers,
  }));
}

export const useFiltersStore = window.__GLOBAL_FILTERS_STORE__;

