import * as geokdbush from 'geokdbush';
import { useDataStore } from '../store/data-store';
import * as turf from '@turf/turf';

const { getKdIndex, getPoints } = useDataStore.getState();

function findNearestStations(lon, lat, { limit = 10, maxDistanceMiles = 50 } = {}) {
  const index = getKdIndex();
  const pts = getPoints();
  const idxs = geokdbush.around(index, lon, lat, limit);
  const withDist = idxs
    .map((i) => {
      const p = pts[i];
      const dMl = turf.distance(turf.point([lon, lat]), turf.point([p.lon, p.lat]), {
        units: 'miles',
      });
      return { ...p, distanceMl: dMl };
    })
    .filter((r) => r.distanceMl <= maxDistanceMiles);
  return withDist.sort((a, b) => a.distanceMl - b.distanceMl);
}

export { findNearestStations };
