import { useDataStore } from '../store/data-store';
import { useTabsStore } from '../store/tabs-store';
import { useFiltersStore } from '../store/filters-store';

const {
  getWaterSheds,
  getWaterBodies,
  getOrganizations,
  getSites,
  getStates,
  getCounties,
  getTowns,
  setAccessibility,
  getCategories,
} = useDataStore.getState();

const {
  setStateFilter,
  setCountyFilter,
  setTownFilter,
  setWaterShedFilter,
  setWaterBodyFilter,
  setOrganizationFilter,
  setSiteFilter,
  setCleanFilter,
  setBoatingFilter,
  setNotCleanFilter,
  setMonthFilter,
  setYearFilter,
  setOldFilter,
  setCategoryFilter,
} = useFiltersStore.getState();

const { setIsAdministrative, setIsOutlook } = useTabsStore.getState();

const querySetMap = {
  state: setStateFilter,
  county: setCountyFilter,
  town: setTownFilter,
  watershed: setWaterShedFilter,
  waterbody: setWaterBodyFilter,
  organization: setOrganizationFilter,
  site: setSiteFilter,
  clean: setCleanFilter,
  boating: setBoatingFilter,
  'not-clean': setNotCleanFilter,
  month: setMonthFilter,
  year: setYearFilter,
  old: setOldFilter,
  administrative: setIsAdministrative,
  quality: setIsOutlook,
  accessibility: setAccessibility,
  category: setCategoryFilter,
};

function initQueries() {
  const urlParams = new URLSearchParams(window.location.search);
  const parsed = {
    administrative:
      urlParams.get('administrative') === 'true'
        ? true
        : urlParams.get('administrative') === 'false'
          ? false
          : undefined,
    quality:
      urlParams.get('quality') === 'true'
        ? true
        : urlParams.get('quality') === 'false'
          ? false
          : undefined,
    watershed: urlParams.get('watershed'),
    waterbody: urlParams.get('waterbody'),
    state: urlParams.get('state'),
    county: urlParams.get('county'),
    town: urlParams.get('town'),
    organization: urlParams.get('organization'),
    site: urlParams.get('site'),
    category: urlParams.get('category'),
    clean:
      urlParams.get('clean') === 'true'
        ? true
        : urlParams.get('clean') === 'false'
          ? false
          : undefined,
    boating:
      urlParams.get('boating') === 'true'
        ? true
        : urlParams.get('boating') === 'false'
          ? false
          : undefined,
    'not-clean':
      urlParams.get('not-clean') === 'true'
        ? true
        : urlParams.get('not-clean') === 'false'
          ? false
          : undefined,
    month:
      urlParams.get('month') === 'true'
        ? true
        : urlParams.get('month') === 'false'
          ? false
          : undefined,
    year:
      urlParams.get('year') === 'true'
        ? true
        : urlParams.get('year') === 'false'
          ? false
          : undefined,
    old:
      urlParams.get('old') === 'true' ? true : urlParams.get('old') === 'false' ? false : undefined,
    accessibility: urlParams.get('accessibility') === '1' ? true : false,
  };

  // console.log(`Parsed:`);
  // console.log(parsed);

  const validatedParams = validateUrlParams(parsed);

  if (Object.values(validatedParams).length > 0) {
    const queryEntries = Object.entries(validatedParams);
    queryEntries.forEach(([key, value]) => {
      querySetMap[key](value);
    });
  }

  // console.log('Validated:');
  // console.log(validatedParams);
}

function validateUrlParams(params) {
  const validatedParams = { ...params };
  const data = createDataState();

  if (
    !validatedParams.watershed ||
    (validatedParams.watershed &&
      !data.watersheds.find((watershed) => watershed.id === validatedParams.watershed))
  )
    delete validatedParams.watershed;
  if (
    !validatedParams.category ||
    (validatedParams.category &&
      !data.categories.find((category) => category.id === validatedParams.category))
  )
    delete validatedParams.category;
  if (
    !validatedParams.waterbody ||
    (validatedParams.waterbody &&
      !data.waterbodies.find((waterbody) => waterbody.id === validatedParams.waterbody))
  )
    delete validatedParams.waterbody;

  if (
    !validatedParams.state ||
    (validatedParams.state && !data.states.find((state) => state.id === validatedParams.state))
  )
    delete validatedParams.state;

  if (
    !validatedParams.county ||
    (validatedParams.county &&
      !data.counties.find((county) => county.id === validatedParams.county))
  )
    delete validatedParams.county;

  if (
    !validatedParams.town ||
    (validatedParams.town && !data.towns.find((town) => town.id === validatedParams.town))
  )
    delete validatedParams.town;

  if (
    !validatedParams.organization ||
    (validatedParams.organization &&
      !data.organizations.find((organization) => organization.id === validatedParams.organization))
  )
    delete validatedParams.organization;

  if (
    !validatedParams.site ||
    (validatedParams.site && !data.sites.find((site) => site.id === validatedParams.site))
  )
    delete validatedParams.site;

  if (typeof validatedParams.administrative !== 'boolean') delete validatedParams.administrative;

  if (typeof validatedParams.quality !== 'boolean') delete validatedParams.quality;

  if (typeof validatedParams.clean !== 'boolean') delete validatedParams.clean;

  if (typeof validatedParams.boating !== 'boolean') delete validatedParams.boating;

  if (typeof validatedParams['not-clean'] !== 'boolean') delete validatedParams['not-clean'];

  if (typeof validatedParams.month !== 'boolean') delete validatedParams.month;

  if (typeof validatedParams.year !== 'boolean') delete validatedParams.year;

  if (typeof validatedParams.old !== 'boolean') delete validatedParams.old;

  return validatedParams;
}

function createDataState() {
  return {
    states: getStates(),
    counties: getCounties(),
    towns: getTowns(),
    watersheds: getWaterSheds(),
    waterbodies: getWaterBodies(),
    organizations: getOrganizations(),
    categories: getCategories(),
    sites: getSites(),
  };
}

function setUrlQuery(param, value) {
  const url = new URL(window.location.href);

  if (value === null || value === undefined || value === '') {
    url.searchParams.delete(param);
  } else {
    url.searchParams.set(param, value);
  }

  window.history.replaceState({}, '', url);
}

export { initQueries, setUrlQuery };
