import { gsap } from './gsap-loader';
const viewport = document.querySelector('#viewport');
const filtersContent = document.querySelector('.map_filters-content');
const imageBar = document.querySelector('.map_image-bar');
const mapLoader = document.querySelector('.map_loader');
const drop = document.querySelector('.map_loader-drop');
window.stop = false;

function hideLoader() {
  window.stop = true;
}

function hideAnimation() {
  if (filtersContent) {
    gsap.to(filtersContent, {
      duration: 0.5,
      opacity: 1,
      pointerEvents: 'all',
      ease: 'power2.out',
    });
  }

  if (mapLoader) {
    gsap.to(mapLoader, {
      duration: 0.5,
      opacity: 0,
      ease: 'power2.out',
      onComplete: () => {
        mapLoader.remove();
      },
    });

    gsap.to(drop, {
      duration: 0.5,
      opacity: 0,
      ease: 'power2.out',
    });

    gsap.to(viewport, {
      opacity: 1,
      duration: 0.5,
      ease: 'power2.out',
    });

    gsap.to(imageBar, {
      duration: 0.5,
      opacity: 1,
      ease: 'power2.out',
    });
  }
}

function processLoader() {
  gsap.set(drop, {
    transform: 'translate(0%, -100%) scale(0%)',
  });
  const timeline = gsap.timeline({ repeat: -1, repeatDelay: 0 });
  timeline
    .to(drop, {
      duration: 0.5,
      transform: 'translate(-50%, -50%) scale(100%)',
    })
    .to(drop, {
      duration: 0.5,
      transform: 'translate(-100%, 0%) scale(0%)',
      onComplete: () => {
        if (window.stop) {
          hideAnimation();
          timeline.kill();
        }
      },
    });
}

export { hideLoader, processLoader };
