import { createStore } from 'zustand/vanilla';

const useFeaturesStore = createStore((set, get) => ({
  sites: new Map(),
  featuresProps: {},
  featuresDrawed: 0,

  setSitesFeatures: (sites) => set(() => ({ sites })),
  setFeaturesProps: (featuresProps) => set(() => ({ featuresProps })),
  setFeaturesDrawed: (featuresDrawed) => set(() => ({ featuresDrawed })),
  getFeaturesDrawed: () => get().featuresDrawed,
  getSiteFeatures: () => get().sites,
  getFeaturesProps: () => get().featuresProps,
}));

export default useFeaturesStore;
