import { useDataStore } from '../store/data-store';
import { initialFiltersState, useFiltersStore } from '../store/filters-store';
import {
  processInputsResets,
  processInputsFiltering,
  filterSites,
  filterStateOptions,
  filterCountyOptions,
  filterTownOptions,
  filterWatershedOptions,
  filterWaterbodyOptions,
  filterOrganizationOptions,
  filterSitesOptions,
  reRenderInputs,
  resetCheckboxes,
  enableResetBtn,
  disableResetBtn,
  handleResetFilterButton,
  filterCategoriesOptions,
} from './filter';
import { setUrlQuery } from './handle-url-queries';
import { updateMarkers, updateBoundaryOutline } from './markers';

const statesSelect = document.querySelector('#states-select');
const countiesSelect = document.querySelector('#counties-select');
const townsSelect = document.querySelector('#towns-select');
const waterShedsSelect = document.querySelector('#watersheds-select');
const waterBodiesSelect = document.querySelector('#waterbodies-select');
const organizationSelect = document.querySelector('#monitoring-select');
const categoriesSelect = document.querySelector('#categories-select');
const sitesSelect = document.querySelector('#sites-select');

const cleanCheckbox = document.querySelector('#clean-swimming');
const boatingCheckbox = document.querySelector('#clean-boating');
const notCleanCheckbox = document.querySelector('#not-clean');

const monthCheckbox = document.querySelector('#month');
const yearCheckboxx = document.querySelector('#year');
const oldCheckbox = document.querySelector('#old');

const {
  setSelectedInputLevel,
  getSelectedInputLevel,
  pushInputHandler,
  clearInputHandlers,
  getInputHandlers,
  setWaterShedFilter,
  setWaterBodyFilter,
  setOrganizationFilter,
  setCategoryFilter,
  setStateFilter,
  setCountyFilter,
  setTownFilter,
  setSiteFilter,
  setCleanFilter,
  setBoatingFilter,
  setNotCleanFilter,
  setYearFilter,
  setMonthFilter,
  setOldFilter,
  getAllFilters,
} = useFiltersStore.getState();

const { setZeroResultsShown, getZeroResultsShown } = useDataStore.getState();

//using filters schema for having uniq logic for all inputs and sorting\reset logic
const filtersInputs = [
  {
    element: statesSelect,
    emptyOption: statesSelect.querySelector('.map_filter-option'),
    dependencyLevel: 0,
    inputParam: 'state',
    setFunction: setStateFilter,
    optionsFilterFunction: filterStateOptions,
    required: true,
  },
  {
    element: countiesSelect,
    emptyOption: countiesSelect.querySelector('.map_filter-option'),
    dependencyLevel: 1,
    inputParam: 'county',
    setFunction: setCountyFilter,
    optionsFilterFunction: filterCountyOptions,
    required: true,
  },
  {
    element: townsSelect,
    emptyOption: townsSelect.querySelector('.map_filter-option'),
    dependencyLevel: 2,
    inputParam: 'town',
    setFunction: setTownFilter,
    optionsFilterFunction: filterTownOptions,
    required: true,
  },
  {
    element: waterShedsSelect,
    emptyOption: waterShedsSelect.querySelector('.map_filter-option'),
    optionsFilterFunction: filterWatershedOptions,
    dependencyLevel: 1,
    setFunction: setWaterShedFilter,
    inputParam: 'watershed',
    required: true,
  },
  {
    element: waterBodiesSelect,
    emptyOption: waterBodiesSelect.querySelector('.map_filter-option'),
    optionsFilterFunction: filterWaterbodyOptions,
    dependencyLevel: 2,
    setFunction: setWaterBodyFilter,
    inputParam: 'waterbody',
    required: true,
  },
  {
    element: organizationSelect,
    emptyOption: organizationSelect.querySelector('.map_filter-option'),
    optionsFilterFunction: filterOrganizationOptions,
    dependencyLevel: 3,
    setFunction: setOrganizationFilter,
    inputParam: 'organization',
    required: true,
  },
  {
    element: categoriesSelect,
    emptyOption: categoriesSelect.querySelector('.map_filter-option'),
    optionsFilterFunction: filterCategoriesOptions,
    dependencyLevel: 4,
    setFunction: setCategoryFilter,
    inputParam: 'category',
    required: false,
  },
  {
    element: cleanCheckbox,
    dependencyLevel: 5,
    setFunction: setCleanFilter,
    inputParam: 'clean',
  },
  {
    element: boatingCheckbox,
    dependencyLevel: 5,
    setFunction: setBoatingFilter,
    inputParam: 'boating',
  },
  {
    element: notCleanCheckbox,
    dependencyLevel: 5,
    setFunction: setNotCleanFilter,
    inputParam: 'not-clean',
  },
  {
    element: monthCheckbox,
    dependencyLevel: 5,
    setFunction: setMonthFilter,
    inputParam: 'month',
  },
  {
    element: yearCheckboxx,
    dependencyLevel: 5,
    setFunction: setYearFilter,
    inputParam: 'year',
  },
  {
    element: oldCheckbox,
    dependencyLevel: 5,
    setFunction: setOldFilter,
    inputParam: 'old',
  },
  {
    element: sitesSelect,
    emptyOption: sitesSelect.querySelector('.map_filter-option'),
    optionsFilterFunction: filterSitesOptions,
    dependencyLevel: 6,
    setFunction: setSiteFilter,
    inputParam: 'site',
    required: true,
  },
];

//Returning function (index) => (e) => {
const createHandler = (index) => (e) => {
  //in handler set selected value
  const prevSelectedLevel = getSelectedInputLevel();
  const selectedInput = filtersInputs[index];

  const zeroResultsShown = getZeroResultsShown();

  let value = e.target.value;
  if (e.target.type === 'checkbox') value = e.target.checked;

  if (e.target.value === 'none') value = '';

  selectedInput.setFunction(value);
  if (e.target.type !== 'checkbox') {
    if (value) {
      selectedInput.element.classList.add('input--active');
      enableResetBtn(selectedInput);
    } else {
      selectedInput.element.classList.remove('input--active');
      disableResetBtn(selectedInput);
    }
  }
  setUrlQuery(selectedInput.inputParam, value);
  // console.log(`Set level: ${selectedInput.dependencyLevel}`);
  setSelectedInputLevel(selectedInput.dependencyLevel);

  if (prevSelectedLevel !== undefined && selectedInput.dependencyLevel < prevSelectedLevel) {
    processInputsResets(selectedInput);
  } else {
    processInputsFiltering(selectedInput);
  }

  const sites = filterSites();

  const points = sites.map((site) => ({ latitude: site.latitude, longitude: site.longitude }));

  const { watershed, waterbody, state, county, town } = getAllFilters();

  const areaFilters = { watershed, waterbody, state, county, town };

  const areaFiltersInputsMap = {
    watershed: 'watershed',
    waterbody: 'waterbody',
    state: 'state',
    county: 'county',
    town: 'town',
  };

  // const isAdministrative = getIsAdministrative();
  const isSelectedArea = Object.values(areaFilters).some((value) => value);
  if (isSelectedArea) {
    if (
      selectedInput.inputParam === 'watershed' ||
      selectedInput.inputParam === 'waterbody' ||
      selectedInput.inputParam === 'state' ||
      selectedInput.inputParam === 'county' ||
      selectedInput.inputParam === 'town'
    ) {
      let boundaryId = value;
      let boundaryType = selectedInput.inputParam;

      if (!value) {
        const activeLowerLevelAreaInputs = Object.entries(areaFilters)
          .map(([key, areaValue]) => {
            const param = areaFiltersInputsMap[key];
            const inputMeta = filtersInputs.find((input) => input.inputParam === param);
            return {
              inputParam: param,
              value: areaValue,
              dependencyLevel: inputMeta?.dependencyLevel ?? Infinity,
            };
          })
          .filter((item) => item.value && item.dependencyLevel < selectedInput.dependencyLevel);

        if (activeLowerLevelAreaInputs.length > 0) {
          const nearest = activeLowerLevelAreaInputs.reduce((a, b) =>
            a.dependencyLevel > b.dependencyLevel ? a : b
          );
          boundaryId = nearest.value;
          boundaryType = nearest.inputParam;
        }
      }

      updateMarkers(sites);
      updateBoundaryOutline({
        checkPoints: points,
        boundaryId: boundaryId,
        boundaryType: boundaryType,
      });
    } else {
      updateMarkers(sites, true);
    }
  } else {
    updateMarkers(sites, true);
    updateBoundaryOutline({ clearOnly: true });
  }

  if (sites.length === 0 && !zeroResultsShown) {
    showZeroResultsOverlay();
  }

  if (sites.length > 0 && zeroResultsShown) {
    hideZeroResultsOverlay();
  }

  // console.log(`filtered ${sites.length} site${sites.length > 1 || sites.length === 0 ? 's' : ''}:`);
  // console.log(sites);
};

function handleInputs(state) {
  filtersInputs.forEach((input, index) => {
    const handler = createHandler(index); //Using creation function for handlers for having oportunity to delete eventListeners in the future
    pushInputHandler(handler);
    input.element.addEventListener('change', handler);

    if (input.element.type !== 'checkbox') {
      const resetFilterBtn = document.querySelector(`#reset-filter-${input.inputParam}`);
      if (resetFilterBtn) {
        resetFilterBtn.addEventListener('click', () => {
          handleResetFilterButton(input);

          const sites = filterSites();
          updateMarkers(sites, true);
        });
      } else {
        console.warn(`Reset button #reset-filter-${input.inputParam} not found`);
      }
    }
  });

  const isBuildFromState = Object.entries(initialFiltersState).some(
    ([key, value]) => state[key] !== value
  );
  if (isBuildFromState) {
    reRenderInputs();
    reRenderInputs(state);
  } else {
    reRenderInputs();
  }

  const resetBtn = document.querySelector('#reset-filters-btn');
  if (resetBtn) {
    resetBtn.addEventListener('click', () => {
      reRenderInputs();
      resetCheckboxes();
      hideZeroResultsOverlay();
      const sites = filterSites();
      updateBoundaryOutline({ clearOnly: true });
      updateMarkers(sites, true);
    });
  } else {
    console.warn('Not found #reset-filters-btn button');
  }
}

function killFilterHandlers() {
  const handlers = getInputHandlers();
  filtersInputs.forEach((input, index) => {
    //go through all handlers and remove listeners
    input.element.removeEventListener('change', handlers[index]);
  });
  clearInputHandlers();
}

function showZeroResultsOverlay() {
  setZeroResultsShown(true);
  const zeroResultsOverlay = document.querySelector('.map_empty-state');
  if (zeroResultsOverlay) zeroResultsOverlay.classList.add('is--active');
  else console.warn('Not found .map_empty-state overlay');
}

function hideZeroResultsOverlay() {
  setZeroResultsShown(false);
  const zeroResultsOverlay = document.querySelector('.map_empty-state');
  if (zeroResultsOverlay) zeroResultsOverlay.classList.remove('is--active');
  else console.warn('Not found .map_empty-state overlay');
}

export { handleInputs, killFilterHandlers, filtersInputs };
