function generateAllMarkerIcons() {
  const qualities = ['clean', 'boat', 'notClean'];
  const relevances = ['month', 'year', 'old'];

  const colorMap = {
    clean: '#1E90FF',
    boat: '#FFBB00',
    notClean: '#ED332F',
  };

  const colorMapAccess = {
    clean: '#0000FF',
    boat: '#FFBB00',
    notClean: '#FF0000',
  };

  for (const quality of qualities) {
    for (const relevance of relevances) {
      for (const isAccess of [false, true]) {
        const suffix = isAccess ? '-access' : '';
        const id = `marker-${quality}-${relevance}${suffix}`;
        const baseColor = isAccess ? colorMapAccess[quality] : colorMap[quality];
        const nearSiteId = `near-${quality}${suffix}`;

        let fill = baseColor;
        let stroke = 'white';
        let strokeWidth = 1;
        let isCircle = false;
        let centerColor = '#ffffffff';

        if (relevance === 'month') {
          isCircle = false;
        } else if (relevance === 'year') {
          fill = 'white';
          stroke = baseColor;
          strokeWidth = 2;
          isCircle = false;
          centerColor = baseColor;
        } else if (relevance === 'old') {
          fill = baseColor;
          stroke = 'white';
          strokeWidth = 1.5;
          isCircle = true;
        }

        const svg = isCircle
          ? generateCircleSvg(fill, stroke, 1, strokeWidth)
          : generateMarkerSvg(fill, stroke, 1, centerColor);

        const highlightedSvg = isCircle
          ? generateCircleSvg(fill, stroke, 1.5, strokeWidth)
          : generateMarkerSvg(fill, stroke, 1.5, centerColor);

        if (!icons.get(nearSiteId)) {
          const nearSiteSvg = generateMarkerSvg(baseColor, 'white', 1, '#0000');
          icons.set(nearSiteId, nearSiteSvg);
        }

        icons.set(id, svg);
        icons.set(`${id}-hightlighted`, highlightedSvg);
      }
    }
  }
}

function generateAllControllsIcons() {
  const collorMap = {
    cloudDark: '#063D57',
    cloudMain: '#566981',
    waterMain: '#1E90FF',
    waterMainAccess: '#0000FF',
  };

  const statesMap = {
    active: collorMap.waterMain,
    activeAccess: collorMap.waterMainAccess,
    initial: collorMap.cloudMain,
    hover: collorMap.cloudDark,
  };

  const iconsMap = {
    zoomIn: generateZoomInIcon,
    zoomOut: generateZoomOutIcon,
    search: generateSearchIcon,
    fullScreen: generateFullScreenIcon,
    compass: generateCompassIcon,
    access: generateAccessIcon,
    mapStyle: generateMapStyleIcon,
  };

  const baseId = 'controll';

  for (const [id, createFunc] of Object.entries(iconsMap)) {
    for (const [state, collor] of Object.entries(statesMap)) {
      const icon = createFunc(collor);
      icons.set(`${baseId}-${id}-${state}`, icon);
    }
  }

  const resetSearchIcon = generateResetSearchIcon();
  icons.set(`controll-reset-search`, resetSearchIcon);
}

export { generateAllMarkerIcons, generateAllControllsIcons, icons };
