import { map } from './maploader';
import { useDataStore } from '../store/data-store';
import useImageBarStore from '../store/image-bar-store';
import useFeaturesStore from '../store/features-store';
import { icons } from './icons-loader';
import {
  highlightMapSite,
  unhighlightMapSite,
  getSiteType,
  waitForFeaturesRendered,
} from './markers';
import htmlToElement from '../utils/html-to-element';
import imageHtml from '../blocks-layout/image.html';
import { gsap } from './gsap-loader';

let imageBarTween = null;
let lasImageBarDirection = null;

const {
  pushSiteHandler,
  clearSiteHandlers,
  getSiteHandlers,
  getIsAnimationPlaying,
  setIsAnimationPlaying,
  getIsActive,
  setIsActive,
} = useImageBarStore.getState();
const { getFeaturesProps } = useFeaturesStore.getState();
const { getLang, getAccessibility } = useDataStore.getState();

export default function makeImageBar() {
  const slider = document.querySelector('.map_image-bar');
  const DRAG_THRESHOLD = 5;
  let isDragging = false;
  let startX = 0;
  let scrollLeft = 0;
  let velocity = 0;

  function onPointerMove(e) {
    if (!isDragging) return;

    const dx = e.clientX - startX;
    const prevScroll = slider.scrollLeft;
    slider.scrollLeft = scrollLeft - dx;
    velocity = slider.scrollLeft - prevScroll;
    if (Math.abs(dx) > DRAG_THRESHOLD && !getIsAnimationPlaying()) {
      setIsAnimationPlaying(true);
    }
  }

  function onPointerUp() {
    slider.classList.remove('dragging');
    isDragging = false;

    animateMomentum();

    window.removeEventListener('pointermove', onPointerMove);
    window.removeEventListener('pointerup', onPointerUp);
  }

  slider.addEventListener('pointerdown', (e) => {
    isDragging = true;
    setIsAnimationPlaying(false);
    startX = e.clientX;
    scrollLeft = slider.scrollLeft;
    velocity = 0;

    slider.classList.add('dragging');

    window.addEventListener('pointermove', onPointerMove);
    window.addEventListener('pointerup', onPointerUp);
  });

  function animateMomentum() {
    const isMobile = window.innerWidth <= 767;
    const distance = velocity * (isMobile ? 20 : 100);
    console.log(distance);
    const targetScroll = slider.scrollLeft + distance;

    gsap.to(slider, {
      scrollTo: {
        x: targetScroll,
        autoKill: true,
      },
      overwrite: true,
      duration: 1,
      ease: 'power3.out',
      onComplete: () => {
        setIsAnimationPlaying(false);
      },
    });
  }

  slider.addEventListener(
    'wheel',
    (e) => {
      const mapboxScrollOverlay = document.querySelector('.mapboxgl-scroll-zoom-blocker');
      if (!mapboxScrollOverlay || getComputedStyle(mapboxScrollOverlay).opacity === '0') {
        e.preventDefault();

        const SCROLL_MULTIPLIER = 2;
        const scrollDelta = (e.deltaX + e.deltaY) * SCROLL_MULTIPLIER;

        gsap.to(slider, {
          scrollTo: {
            x: slider.scrollLeft + scrollDelta,
            autoKill: true,
          },
          duration: 0.4,
          ease: 'power2.out',
        });
      }
    },
    { passive: false }
  );

  map.on('moveend', () => {
    waitForFeaturesRendered('site-points', (features) => {
      updateVisibleList(features);
    });
  });

  map.on('manualUpdate', () => {
    const visibleSites = getVisibleSites();
    updateVisibleList(visibleSites);
  });

  waitForFeaturesRendered('site-points', (features) => {
    updateVisibleList(features);
  });
}

function getVisibleSites() {
  const mapCanvas = map.getCanvas();
  const imageBar = document.querySelector('.map_image-bar');
  const mapWidth = mapCanvas.clientWidth;
  const mapHeight = mapCanvas.clientHeight;
  const imageBarHeight = imageBar.clientHeight;
  const padding = 20;

  const visiblePixelBounds = [
    [padding, padding],
    [mapWidth - padding, mapHeight - imageBarHeight - padding],
  ];

  const features = map.queryRenderedFeatures(visiblePixelBounds, {
    layers: ['site-points-layer'],
  });

  const unique = new Map();
  for (const feature of features) {
    const id = feature.properties.id;
    if (!unique.has(id)) {
      unique.set(id, feature.properties);
    }
  }

  return [...unique.values()];
}

const createSiteHandler = () => (e) => {
  const isAnimanionPlaying = getIsAnimationPlaying();
  if (isAnimanionPlaying) e.preventDefault();
};

function killSiteHandlers() {
  const handlersMap = getSiteHandlers();
  for (const [el, handlers] of handlersMap) {
    handlers.forEach((handler) => {
      el.removeEventListener('click', handler);
    });
    const siteId = el.getAttribute('data-site-id');
    unhighlightMapSite(siteId);
  }
  clearSiteHandlers();
}

function cropText(text, size = 18) {
  if (text.length > size) {
    return `${text.substring(0, size).trim()}...`;
  }
  return text;
}

function toggleImageBar(forceState = null) {
  const container = document.querySelector('.map_image-bar');
  if (!container) return;

  const height = container.offsetHeight;
  const currentTransform = gsap.getProperty(container, 'y');

  const isCurrentlyVisible = currentTransform <= 0.1;
  const shouldShow = forceState !== null ? forceState : !isCurrentlyVisible;

  const targetY = shouldShow ? 0 : height;
  const direction = shouldShow ? 'up' : 'down';

  if (direction === lasImageBarDirection && imageBarTween) return;

  if (shouldShow) {
    container.style.display = 'flex';
  }

  imageBarTween?.kill();

  imageBarTween = gsap.to(container, {
    y: targetY,
    duration: 0.5,
    ease: 'power3.out',
    onComplete: () => {
      if (!shouldShow) {
        container.style.display = 'none';
      }
      imageBarTween = null;
      lasImageBarDirection = null;
    },
  });

  lasImageBarDirection = direction;
}

function updateVisibleList(sites) {
  const isActive = getIsActive();
  const featuresProps = getFeaturesProps();

  killSiteHandlers();
  const filteredSites = sites
    .map((site) => {
      return {
        ...site,
        ...featuresProps[site.id],
      };
    })
    .filter((site) => site.image)
    .filter((site, index) => index < 20);
  const container = document.querySelector('.map_image-bar');
  container.innerHTML = '';

  if (filteredSites.length === 0 && isActive) {
    setIsActive(false);
    toggleImageBar(false);
  }

  if (filteredSites.length > 0 && !isActive) {
    setIsActive(true);
    toggleImageBar(true);
  }

  let baseUrl = window.location.host;
  const lang = getLang();

  if (lang === 'es');
  baseUrl += '/es';

  filteredSites.forEach((site) => {
    const imageFormatedHtml = imageHtml
      .replace('SITE_ID', site.id)
      .replace('SITE_LINK', `/${lang === 'es' ? 'es/' : ''}sites/${site.slug}`)
      .replace(
        'SITE_IMAGE',
        site.image
          ? `<img src="${site.image}" class="map_site-img" alt="Monitoring site image" height="100%" width="100%">`
          : ''
      )
      .replace('SITE_ICON', getMarkerSvgFromSite(site))
      .replace('SITE_NAME', cropText(site.name));

    const el = htmlToElement(imageFormatedHtml);

    const highlightFunction = (e) => {
      if (!e.pointerType || e.pointerType !== 'mouse') return;
      highlightMapSite(site.id, site);
    };

    const unHighlightFunction = (e) => {
      if (!e.pointerType || e.pointerType !== 'mouse') return;
      unhighlightMapSite();
    };

    const handler = createSiteHandler();
    el.addEventListener('click', handler);
    el.addEventListener('pointerenter', highlightFunction);
    el.addEventListener('pointerleave', unHighlightFunction);
    pushSiteHandler([el, [handler, highlightFunction, unHighlightFunction]]);
    container.appendChild(el);
  });
}

function getMarkerSvgFromSite(site, qualityOnly = false, code = 'marker') {
  const access = getAccessibility();
  const siteType = getSiteType(site);
  const iconId = `${code}-${siteType.quality}${qualityOnly ? '' : `-${siteType.relevance}`}${access ? '-access' : ''}`;
  const iconUrl = icons.get(iconId);
  if (!iconUrl) {
    console.error(`Icon with id ${iconId} not found`);
  }
  return iconUrl;
}

export { getMarkerSvgFromSite, cropText };
