import { createStore } from 'zustand/vanilla';

const useImageBarStore = createStore((set, get) => ({
  siteHandlers: new Map(),
  isAnimanionPlaying: false,
  isActive: false,

  setIsAnimationPlaying: (isAnimanionPlaying) => set(() => ({ isAnimanionPlaying })),
  pushSiteHandler: ([key, value]) =>
    set((state) => ({ siteHandlers: state.siteHandlers.set(key, value) })),
  clearSiteHandlers: () => set(() => ({ siteHandlers: new Map() })),
  setIsActive: (isActive) => set(() => ({ isActive })),

  getSiteHandlers: () => get().siteHandlers,
  getIsAnimationPlaying: () => get().isAnimanionPlaying,
  getIsActive: () => get().isActive,
}));

export default useImageBarStore;
