import mapboxgl from 'mapbox-gl';
import AccessibilityControl from './access-controll';
import { generateAllControllsIcons, icons } from './icons-loader';
import { useDataStore } from '../store/data-store';
import MapStyleControll from './map-style-controll';
import MapboxGeocoder from '@mapbox/mapbox-gl-geocoder';

const { getMapStyle } = useDataStore.getState();
generateAllControllsIcons();
const isMapPage = window.location.pathname.includes('/map');
const isMobile = window.innerWidth <= 767;

function renderMap() {
  const style = getMapStyle();
  mapboxgl.accessToken =
    'pk.eyJ1Ijoicm9kb25uZWxsLWN0cml2ZXIiLCJhIjoiY21kaGoxb3dwMDI5NDJscHp6djk0aHIzZiJ9.SAf5EWG05FFg3-5Vkd1c6A';
  const map = new mapboxgl.Map({
    container: 'viewport',
    projection: 'mercator',
    style: style,
    center: [-72.61177, 42.58554],
    zoom: 6.3,
    attributionControl: false,
    pixelRatio: window.devicePixelRatio || 1,
    cooperativeGestures: isMapPage && !isMobile ? false : true,
  });
  return map;
}

const map = renderMap();
const mapCanvas = map.getCanvas();
mapCanvas.style.position = 'relative';

map.addControl(new mapboxgl.AttributionControl(), 'top-right');
map.addControl(
  new MapboxGeocoder({
    accessToken: mapboxgl.accessToken,
    mapboxgl: mapboxgl,
    marker: false,
    placeholder: ' ',
    collapsed: true,
  })
);
map.addControl(new mapboxgl.FullscreenControl(), 'top-right');
map.addControl(new mapboxgl.NavigationControl(), 'top-right');
if (isMapPage) map.addControl(new AccessibilityControl(), 'top-right');
map.addControl(new MapStyleControll(), 'top-right');

processDynamicCss();
processSearchIcons();

function processDynamicCss() {
  const bottomControlls = document.querySelectorAll('.mapboxgl-ctrl-bottom-left');
  bottomControlls.forEach((control) => {
    control.classList.replace('mapboxgl-ctrl-bottom-left', 'mapboxgl-ctrl-top-left');
  });

  const defaultSelectorBase = '.mapboxgl-ctrl button.$base .mapboxgl-ctrl-icon';
  const pseudoSelectorBase =
    '.mapboxgl-ctrl button.$base:not(.$base--active) .mapboxgl-ctrl-icon:$pseudo';
  const activeSelectorBase = '.mapboxgl-ctrl button.$base.$base--active .mapboxgl-ctrl-icon';
  const accessSelectorBase =
    '.mapboxgl-ctrl button.$base.$base--access.$base--active .mapboxgl-ctrl-icon';
  const selectorValues = `{ background-image: url($icon) }`;
  const onlyAccessBase = `.mapboxgl-ctrl button.$base.$base--access .mapboxgl-ctrl-icon`;

  const hoverCssBase = `@media (hover: hover) and (pointer: fine) {\n$selectors}\n`;
  const activeCssBase = `@media (hover: none) and (pointer: coarse) {\n$selectors}\n`;

  const stateMap = {
    hover: [
      { class: 'mapboxgl-ctrl-zoom-in', icon: 'controll-zoomIn-hover' },
      { class: 'mapboxgl-ctrl-zoom-out', icon: 'controll-zoomOut-hover' },
      { class: 'mapboxgl-ctrl-compass', icon: 'controll-compass-hover' },
      { class: 'mapboxgl-ctrl-fullscreen', icon: 'controll-fullScreen-hover' },
      { class: 'mapboxgl-ctrl-access', icon: 'controll-access-hover' },
      { class: 'mapboxgl-ctrl-map-style', icon: 'controll-mapStyle-hover' },
    ],
    active: [
      { class: 'mapboxgl-ctrl-access', icon: 'controll-access-active' },
      { class: 'mapboxgl-ctrl-map-style', icon: 'controll-mapStyle-active' },
    ],
    activeAccess: [
      { class: 'mapboxgl-ctrl-access', icon: 'controll-access-activeAccess' },
      { class: 'mapboxgl-ctrl-map-style', icon: 'controll-mapStyle-activeAccess' },
    ],
    initial: [
      { class: 'mapboxgl-ctrl-zoom-in', icon: 'controll-zoomIn-initial' },
      { class: 'mapboxgl-ctrl-zoom-out', icon: 'controll-zoomOut-initial' },
      { class: 'mapboxgl-ctrl-compass', icon: 'controll-compass-initial' },
      { class: 'mapboxgl-ctrl-fullscreen', icon: 'controll-fullScreen-initial' },
      { class: 'mapboxgl-ctrl-shrink', icon: 'controll-fullScreen-active' },
      { class: 'mapboxgl-ctrl-access', icon: 'controll-access-initial' },
      { class: 'mapboxgl-ctrl-map-style', icon: 'controll-mapStyle-initial' },
    ],
    access: [{ class: 'mapboxgl-ctrl-shrink', icon: 'controll-fullScreen-activeAccess' }],
  };

  let defaultSelectors = '';
  let hoverSelectors = '';
  let activeSelectors = '';

  for (const [state, objects] of Object.entries(stateMap)) {
    for (const { class: elementClass, icon } of objects) {
      let targetBase;
      if (state === 'hover') {
        targetBase = pseudoSelectorBase;
      }

      if (state === 'active') {
        targetBase = activeSelectorBase;
      }

      if (state === 'activeAccess') {
        targetBase = accessSelectorBase;
      }

      if (state === 'access') {
        targetBase = onlyAccessBase;
      }

      if (!targetBase) {
        targetBase = defaultSelectorBase;
      }

      const targetIcon = icons.get(icon);
      const selector = targetBase.replaceAll('$base', elementClass).replaceAll('$pseudo', 'hover');
      const result = `${selector}${selectorValues.replace('$icon', targetIcon)}\n`;

      if (state === 'hover') {
        hoverSelectors += result;
        activeSelectors += `${targetBase.replaceAll('$base', elementClass).replaceAll('$pseudo', 'active')}${selectorValues.replace('$icon', targetIcon)}`;
      }
      if (
        state === 'initial' ||
        state === 'active' ||
        state === 'activeAccess' ||
        state === 'access'
      )
        defaultSelectors += result;
    }
  }

  const style = document.createElement('style');
  style.innerHTML = `
    ${defaultSelectors}\n
    ${hoverCssBase.replace('$selectors', hoverSelectors)}\n
    ${activeCssBase.replace('$selectors', activeSelectors)}`;

  document.body.append(style);
}

function processSearchIcons() {
  const searchIcon = document.querySelector('.mapboxgl-ctrl-geocoder--icon-search');
  const resetIcon = document.querySelector('.mapboxgl-ctrl-geocoder--icon-close');
  const classListSearch = searchIcon.classList;
  const spanSearch = document.createElement('span');
  spanSearch.classList.add(...classListSearch);
  searchIcon.replaceWith(spanSearch);

  const classListReset = resetIcon.classList;
  const spanReset = document.createElement('span');
  spanReset.classList.add(...classListReset);
  resetIcon.replaceWith(spanReset);

  const style = document.createElement('style');
  style.innerHTML = `.mapboxgl-ctrl-geocoder--icon-search {background: no-repeat center center url(${icons.get('controll-search-hover')})} .mapboxgl-ctrl-geocoder.mapboxgl-ctrl-geocoder--collapsed 
  .mapboxgl-ctrl-geocoder--icon-search {background: no-repeat center center url(${icons.get('controll-search-initial')})} .mapboxgl-ctrl-geocoder--icon-close {background: no-repeat center center url(${icons.get('controll-reset-search')})}
  `;
  document.body.append(style);
}

export { map, mapboxgl };
