import { useDataStore } from '../store/data-store';
import { icons } from './icons-loader';
import { cropText, getMarkerSvgFromSite } from './image-bar';
import { getSiteType } from './markers';
import { findNearestStations } from './nearest-stations';
const { setUserLocation, getSites, getLang, getAccessibility } = useDataStore.getState();

async function getUserCoords() {
  if ('geolocation' in navigator) {
    try {
      const position = await new Promise((resolve, reject) => {
        navigator.geolocation.getCurrentPosition(resolve, reject, {
          enableHighAccuracy: true,
        });
      });

      return {
        lat: position.coords.latitude,
        lon: position.coords.longitude,
      };
    } catch (err) {
      console.warn('Geolocation failed:', err.message);
    }
  } else {
    console.warn('Geolocation is not supported in this browser.');
  }

  try {
    const res = await fetch('https://ipwho.is/');
    const data = await res.json();

    if (data.success) {
      return {
        lat: data.latitude,
        lon: data.longitude,
      };
    } else {
      console.warn('IP lookup failed:', data.message);
    }
  } catch (err) {
    console.error('Error fetching IP-based location:', err);
  }

  return undefined;
}

async function buildSitesNearby() {
  await waitAnimation();
  const coords = await getUserCoords();
  if (coords) {
    setUserLocation(coords);
    // console.log(getUserLocation());
    const nearestStations = findNearestStations(coords.lon, coords.lat, {
      limit: 3,
      maxDistanceMiles: 100,
    });
    if (nearestStations.length > 0) {
      const sites = getSites();
      const result = [];

      nearestStations.forEach((site) => {
        result.push({ ...sites[site.idx], distance: site.distanceMl });
      });

      fillNearestBlock(result);
    }
  }
}

function fillNearestBlock(sites) {
  const nearestSitesBlock = document.querySelector('#closest-block');
  const waterQualityBtn = document.querySelector('.no-closest-sites');
  const nearestSitesWrapper = nearestSitesBlock.querySelector('#closest-wrapper');
  const itemTemplate = nearestSitesWrapper.querySelector('.c_stats-item');

  const itemIcon = itemTemplate.querySelector('svg');
  const img = document.createElement('img');
  itemIcon.replaceWith(img);

  const nameClass = 'c_stats-item_name';
  const milesClass = 'c_stats-item_miles';

  const lang = getLang();

  nearestSitesWrapper.innerHTML = '';

  sites.forEach((site) => {
    const siteType = getSiteType(site);
    const itemElement = itemTemplate.cloneNode(true);

    const icon = itemElement.querySelector('img');
    icon.classList.add('site_nearby_quality-icon');
    icon.setAttribute('data-quality', siteType.quality);
    const iconUrl = getMarkerSvgFromSite(site, true, 'near');

    icon.src = iconUrl;

    const nameTextBlock = itemElement.querySelector(`.${nameClass}`);
    nameTextBlock.textContent = cropText(site.name, 40);

    const milesTextBlock = itemElement.querySelector(`.${milesClass}`);
    milesTextBlock.textContent = `${site.distance.toFixed(1)}mi`;

    const url = `/${lang === 'es' ? 'es/' : ''}sites/${site.slug}`;
    itemElement.href = url;

    nearestSitesWrapper.append(itemElement);
  });
  nearestSitesBlock.classList.remove('c_stats-hide');
  waterQualityBtn.remove();
}

async function waitAnimation() {
  if (window.loaderAnimationDone) {
    return new Promise((resolve) => {
      resolve();
    });
  } else {
    return new Promise((resolve) => {
      window.onCompleteLoader = resolve;
    });
  }
}

function updateIconsByAccess() {
  const access = getAccessibility();
  const siteIcons = document.querySelectorAll('.site_nearby_quality-icon');
  siteIcons.forEach((icon) => {
    const quality = icon.getAttribute('data-quality');
    icon.src = icons.get(`near-${quality}${access ? '-access' : ''}`);
  });
}

export { getUserCoords, buildSitesNearby, updateIconsByAccess };
